# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_mis_b import M
C=M+[['中古英语 mis- + carry → miscarien','走偏、受损，未达到原定结果'],['英语 miscarry','计划失败；妊娠自然终止']]
F=[['英语 miss fire，或 mis- + fire；两种形式可能汇合','未能正常发火'],['misfire','未正常点火或发射；行动没有达到预期效果']]
WE=[
E('miscarry','英 /ˌmɪsˈkæri/；美 /ˌmɪsˈkæri/','自然流产；〔计划等〕失败、未遂','历史核心是事情没有顺利达到原定结果，后来分别用于计划和妊娠。','mis- + carry，词形可拆，语义不能机械译成“搬错了”。',C,'现代日常英语里，miscarry 常指妊娠自然终止；较正式的文字还会说计划或行动 miscarried。词源中的 mis- 描述结果不顺，并不说明发生了什么原因，更不是对当事人的指责。','miscarry during pregnancy；a plan miscarried；the scheme miscarried。','miscarry 是动词，miscarriage 是名词。谈妊娠时它通常不是主动终止妊娠的说法。',('She wrote about the grief she felt after she miscarried.','她写下了自己自然流产后的悲伤。'),('Their plan miscarried when the funding disappeared.','资金没了，他们的计划也随之失败。'),sources=['https://www.etymonline.com/word/miscarry','https://www.nhs.uk/conditions/miscarriage/']),
E('miscarriage','/ˈmɪskærɪdʒ/','自然流产；失败；司法失误〔用于固定搭配〕','同一个“过程出了问题”的旧意，分出妊娠和司法等不同语境。','联系 miscarry 与名词结尾 -age；也可按 mis- + carriage 分析表面结构。这里 carriage 不能只理解成马车。',C+[['英语 miscarriage','过程出错；后来用于自然流产等情形'],['miscarriage of justice','司法过程未实现公正，尤其造成错误定罪等严重不公']],'单独说 have a miscarriage，通常指自然流产。a miscarriage of justice 是完整搭配，讲司法不公或重大错判，不应拆译成“正义流产”。这两个现代用法各有自己的语境，不能见到 miscarriage 就只想到其中一个。','have a miscarriage；support after a miscarriage；a miscarriage of justice。','miscarriage 是名词，miscarry 是动词。miscarriage of justice 与 mistrial 不同：后者说某次审判未能有效完成，并不自动意味着已经发生冤案。',('The charity offers support after a miscarriage.','这家慈善机构为经历自然流产的人提供支持。'),('The documentary examines a serious miscarriage of justice.','这部纪录片探讨了一起严重的司法不公案件。'),sources=['https://www.etymonline.com/word/miscarriage','https://www.nhs.uk/conditions/miscarriage/']),
E('misfit','/ˈmɪsfɪt/','不合群的人；与环境不适配的人或物','像一块拼图放进了不合适的位置，问题在于它与周围对不上。','mis- + fit“适合、合身”；从不适配发展出人融不进环境的比喻。',M+[['英语 mis- + fit','不合适、不相配'],['misfit','与环境、群体或用途不相适配的人或物']],'feel like a misfit 是觉得自己与周围格格不入。它不等于人本身没有价值，也可能只是兴趣、性格与当下群体不合。在故事里，a group of misfits 常是一群不被主流接纳的人聚在一起。','feel like a misfit；a social misfit；a group of misfits。','loner 强调常独来独往；misfit 强调融不进去或不适合环境。独处可能是选择，不一定来自不适配。',('I felt like a misfit during my first week at the new school.','在新学校的第一周，我觉得自己格格不入。'),('The film follows a group of misfits who become friends.','电影讲述一群不合群的人逐渐成为朋友的故事。'),sources=['https://en.wiktionary.org/wiki/misfit','https://www.etymonline.com/word/misfit']),
E('mistrial','/ˈmɪstraɪəl/','无效审判；未能有效结束的审判','审判这趟程序走不下去，或不能产生应有的法律结果。','mis- + trial“审判”；不能只按字面理解成“法官判错了”。',M+[['英语 mis- + trial','存在问题的审判'],['法律语境 mistrial','因严重程序问题、陪审团僵局等而未能有效完成的审判']],'新闻中的 declare a mistrial 是宣布这次审判无效或不能正常完成。它可能与程序错误或陪审团无法达成裁决有关。重点是本次审理的状态，不等于宣布被告无罪，也不等于已经证明判决冤枉了人。','declare a mistrial；end in a mistrial；a request for a mistrial。','acquittal 是无罪裁决；mistrial 是本次审判未能有效结束。miscarriage of justice 则强调严重的司法不公。',('The judge declared a mistrial after a serious procedural error.','出现严重程序错误后，法官宣布此次审判无效。'),('The case ended in a mistrial when the jury could not agree.','陪审团无法达成一致，这次审判未能有效结束。'),sources=['https://www.merriam-webster.com/dictionary/mistrial','https://en.wiktionary.org/wiki/mistrial']),
E('misappropriation','/ˌmɪsəprəʊpriˈeɪʃən/；美 /ˌmɪsəproʊpriˈeɪʃən/','侵占；挪用；不当占用','原本有指定归属或用途的东西，被人不当地拿走、占有或转用了。','mis- + appropriation“占用、拨用”；与动词 misappropriate 相连。',M+[['英语 appropriation 加 mis-','不当地占有或挪用'],['misappropriation','侵占、挪用等行为']],'misappropriation of funds 常指挪用资金；也可谈他人的资料、作品等被不当据为己有。不要把它理解成普通“分配得不够好”：这个词常涉及归属、授权或用途的问题。','misappropriation of funds；misappropriation of company assets；an allegation of misappropriation。','misallocation 是分配不当；misappropriation 更强调不当地拿取、占用或挪作他用。二者不能直接互换。',('The audit uncovered evidence of misappropriation of company funds.','审计发现了公司资金被挪用的证据。'),('The dispute concerns the alleged misappropriation of research materials.','争议涉及研究资料被指遭到不当占用。'),sources=['https://en.wiktionary.org/wiki/misappropriation','https://www.merriam-webster.com/dictionary/misappropriation']),
E('mistreat','/ˌmɪsˈtriːt/','虐待；恶劣地对待','对象是一个人或动物，问题出在你怎样对待它，而非你怎样理解它。','mis- “恶劣、不当” + treat“对待”。',M+[['英语 mis- + treat','以不好的方式对待'],['mistreat','恶劣对待，程度可到虐待']],'mistreat someone 可以是羞辱、苛待或伤害等不良对待。treat 在这里不是“请客”的意思，也不是只限于医疗治疗。翻译成“虐待”还是“恶劣对待”，要看行为程度。','mistreat workers；mistreat animals；be mistreated by someone。','misbehave 是自己行为不当；mistreat 后面常接受到不当对待的对象。mistreat animals 不等于 misuse a tool。',('The report describes how workers were mistreated at the factory.','报告描述了工人在那家工厂受到怎样的恶劣对待。'),('The shelter cares for animals that have been mistreated.','这家收容所照料曾受到虐待的动物。'),sources=['https://en.wiktionary.org/wiki/mistreat','https://www.etymonline.com/word/mistreat']),
E('misfire','英 /ˌmɪsˈfaɪə/；美 /ˌmɪsˈfaɪər/','未正常点火、发射；失败；产生不理想的效果','本来期待“这一下会起作用”，结果没打响，甚至弄巧成拙。','可能来自短语 miss fire 连写，也可联系 mis- + fire，两条形式可能汇合。',F,'发动机 misfires 是燃烧、点火没有正常配合；a joke misfires 是笑话没有逗笑，反而冷场或惹人不快。比喻义保留了“该有的效果没有正常出来”的画面。','an engine misfires；a joke misfires；a campaign misfires。','backfire 更明确表示产生与预期相反的后果；misfire 可以只是没成功，也可能产生不良效果。',('The engine began to misfire on the way home.','回家途中，发动机开始点火不正常。'),('His attempt at humor misfired and made the room go quiet.','他想开个玩笑，却弄巧成拙，让整个房间安静了下来。'),sources=['https://en.wiktionary.org/wiki/misfire','https://www.etymonline.com/word/misfire']),
E('misadventure','英 /ˌmɪsədˈventʃə/；美 /ˌmɪsədˈventʃər/','不幸遭遇；意外事故；倒霉经历','原本是一次经历，结果一路出岔子，变成了倒霉故事。','现代看似 mis- + adventure；历史来自古法语 mesaventure，mes- 与拉丁 minus 的路线有关，不能全归到日耳曼 mis-。',[['拉丁 minus 的罗曼语发展 → 古法语 mes-；加 aventure“偶然发生的事”','不好的遭遇'],['古法语 mesaventure → 中古英语 misaventure','不幸、事故'],['英语 misadventure','后来恢复 d 的拼写；不幸经历、意外事故']],'misadventure 在旅行故事里可以带轻松语气，说一连串倒霉经历；正式语境里也能指严重意外。adventure 的早期意义更接近“发生的事、遭遇”，所以本词不是单纯“冒险做错了”。','travel misadventures；a series of misadventures；an unfortunate misadventure。','adventure 常带新奇、刺激感，misadventure 强调不幸或出错的经过。不能只凭词尾 adventure 就翻成有趣冒险。',('She turned her travel misadventures into a funny book.','她把旅途中的倒霉经历写成了一本有趣的书。'),('After a series of misadventures, we finally reached the village.','接连遇到几次不顺后，我们终于到了村子。'),sources=['https://www.etymonline.com/word/misadventure','https://en.wiktionary.org/wiki/misadventure']),
]
